// std::string under MSVC x64, the release CRT's here, for core/nvrhi.ts (its import of "./nvrhi_abi"
// takes this file on Windows, core/nvrhi_abi.linux.ts on Android): debug names for the descs NVRHI
// takes. The classes and the structs, generated by tools/gen_nvrhi_classes.py, are in
// core/nvrhi_classes.win32.ts, with std::string as the CRT lays it out (basic_string_char).
//
// That layout depends on the C++ build (the debug CRT's std::string is bigger): nvrhi.layoutMatches()
// checks the descs' sizes with Donut_GetNvrhiStructSize.

import "./nvrhi_classes";

export namespace nvrhi {

    // std::string with the release CRT the project builds with (32 bytes): the short-string buffer
    // (_Bx, 16 bytes, what fits in it is stored there), the size and the capacity (15 while short)
    export type StdString = basic_string_char;

    // An std::string holding name, for a desc's debugName: only a short string (15 characters or
    // fewer) can be made here, as a longer one is allocated by C++; empty for a longer name.
    export function stdString(name: string): StdString {
        const empty: StdString = [[[[0, 0], 0, 15]]];
        const chars = <Ref<u8>><Opaque>name;
        let size = 0;
        while (Deref(chars[size]) != 0) {
            size++;
            if (size > 15) {
                return empty;
            }
        }

        let buffer0: u64 = 0;
        let buffer1: u64 = 0;
        let shift: u64 = 1;
        for (let i = 0; i < size; i++) {
            if (i == 8) {
                shift = 1;
            }
            const char: u64 = Deref(chars[i]);
            if (i < 8) {
                buffer0 += char * shift;
            } else {
                buffer1 += char * shift;
            }
            shift *= 256;
        }

        return [[[[buffer0, buffer1], size, 15]]];
    }

    // An std::string's size
    export function stdStringSize(value: StdString): int {
        return <int>value._Mypair._Myval2._Mysize;
    }

    // Whether an std::string (NVRHI's copy of a debug name, say) is short and holds text: its
    // characters and terminating zero, read byte by byte from its buffer (_Bx, at its start)
    export function stdStringIs(value: StdString, text: string): boolean {
        const size = stdStringSize(value);
        if (size > 15) {
            return false;
        }

        const chars = <Ref<u8>><Opaque>text;
        let copy = value;
        const bytes = <Ref<u8>><Opaque>Ref(copy);
        for (let i = 0; i <= size; i++) {
            if (Deref(bytes[i]) != Deref(chars[i])) {
                return false;
            }
        }

        return true;
    }

    // MSVC's std::vector: _Mypair._Myval2 {_Myfirst, _Mylast, _Myend}
    // A std::vector<T> over items' elements, for a desc NVRHI copies: nothing destroys it here,
    // and items has to stay alive during the call.
    export function stdVector<T>(items: T[]): vector<T> {
        if (items.length == 0) {
            return [[[null, null, null]]];
        }

        const first = Ref(items[0]);
        const end = <Ref<T>><Opaque>(<index><Opaque>first + items.length * sizeof<T>());
        return [[[first, end, end]]];
    }

    // A std::vector<T>'s size
    export function stdVectorSize<T>(items: vector<T>): int {
        const a = <index><Opaque>items._Mypair._Myval2._Myfirst;
        const b = <index><Opaque>items._Mypair._Myval2._Mylast;
        return <int>((b - a) / sizeof<T>());
    }

    // A std::vector<T>'s element i (below stdVectorSize)
    export function stdVectorAt<T>(items: vector<T>, i: int): Ref<T> {
        return <Ref<T>><Opaque>(<index><Opaque>items._Mypair._Myval2._Myfirst + i * sizeof<T>());
    }
}
